    for (const row of b.ticks) ticks.push(row);
    for (const l of b.liquidations) liquidations.push(l);
    for (const l of (b.loads || [])) loads.push(l);
    for (const l of (b.samples || [])) samples.push(l);
    for (const l of (b.tapes || [])) tapes.push(l);
