  if (signature.length !== FINAL_SIG_SIGNATURE_BYTES) throw new Error(`a signature is ${FINAL_SIG_SIGNATURE_BYTES} bytes, got ${signature.length}`);
  const out = new Uint8Array(SIGNED_FINAL_SIG_BYTES);
  out.set(body, 0);
