    const f = k.startsWith(PENDING_PREFIX) ? k.slice(PENDING_PREFIX.length)
      : k.startsWith(LEDGER_PREFIX) && !k.startsWith(LEDGER_READ_PREFIX) ? k.slice(LEDGER_PREFIX.length) : null;
