  try { want = g.target === GIFT_TO_BOTH ? giftOutputs({ totalMsat: g.totalMsat, networkSet, gameSet }) : giftOutputs({ totalMsat: g.totalMsat, recipients }); } catch (e) { return { ok: false, why: e.message }; }
