// A HEAD-TO-HEAD ROUND, FROM THE PAGE: the player's hidden move, its reveal to the round's seats after entry
// close, and the reveals the seats hold - for any head-to-head game; which moves a game has, and what beats what, are the
// game's own (its client and its decide adapter). The commitment is the protocol's (arena-protocol head-to-head.js); the
// entry itself is built and handed over as a market pick's is (join.js entryFor, market.js submitPick), with `commit` set.

const h2hHex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');

/** A move and a fresh 32-byte salt to hide it with; `random(n)` is the page's CSPRNG. */
function hiddenMove(move, random) {
  if (!Number.isInteger(move) || move < 0 || move > 255) throw new Error('a move is a byte');
  return { move, salt: random(32) };
}

/** The commitment an entry into `roundId` under session key `sessionPubkey` names for that hidden move. */
function moveCommitment({ roundId, sessionPubkey, move, salt }) {
  return headToHeadCommit({ roundId, entryKey: sessionPubkey, move, salt });
}

/** The reveal to every seat: POST /reveal?entry= { move, salt }. Answers each seat's status. */
// `identity`: { key, sig } (identity.js identityProofFor) - the tab's identity on this entry, for a score across rounds
async function revealMove({ entryIdHex, move, salt, nodes, identity = null, fetcher = fetch }) {
  const body = JSON.stringify({ move, salt: salt instanceof Uint8Array ? h2hHex(salt) : String(salt), ...(identity ? { identity } : {}) });
  return Promise.all(nodes.map(async (node) => {
    try {
      const r = await fetcher(`${String(node).replace(/\/+$/, '')}/reveal?entry=${entryIdHex}`, { method: 'POST', body });
      return { node, status: r.status, why: r.status === 200 || r.status === 201 ? null : (await r.text()).trim() };
    } catch (e) { return { node, status: 0, why: e.message }; }
  }));
}

/** Every reveal the round's seats hold, merged by entry: { [entryIdHex]: move }. */
async function revealsOfRound({ roundIdHex, nodes, fetcher = fetch }) {
  const out = {};
  await Promise.all(nodes.map(async (node) => {
    try {
      const r = await fetcher(`${String(node).replace(/\/+$/, '')}/reveals?round=${roundIdHex}`);
      if (!r.ok) return;
      const j = await r.json();
      for (const x of (j && Array.isArray(j.reveals) ? j.reveals : [])) if (Number.isInteger(x.move)) out[x.entry] = x.move;
    } catch { /* a seat that is down says nothing */ }
  }));
  return out;
}

// ---- arena-protocol/src/game-info.js
// SPDX-License-Identifier: LicenseRef-Bitcoin-Arena-1.0
// Copyright (c) 2026 The Bitcoin Arena authors. See LICENSE.
// A GAME'S DESCRIPTION AND WEBSITE, SIGNED BY ITS DEVELOPER (2026-10-11: "Das Manifest soll auch eine
// Description und Webseite haben die signiert wird, die hier angezeigt wird"; and ~06:55Z: "Mach es so dass beide hashes
// akzeptiert werden - mit URL und ohne URL, mit Description und ohne").
//
// THEY TRAVEL BESIDE THE MANIFEST, NOT IN ITS BYTES. game_id = H(manifest body || signature) (manifest.js gameIdOf), and
// the seats' advertisements, every published series and every market name those ids. So the info is its own small object:
// the developer key the manifest names signs H(game_id || description || website), and a manifest with it and the same
// manifest without it are one game with one id. An info whose signature does not stand is shown as unsigned, never trusted.
//
// AND WHERE TIPS GO (tips to developers): a Lightning address (name@host, LUD-16) the developer signs
// beside the two strings. It is appended to the digest only when there is one, so every info signed before it - with no
// address - keeps its digest byte for byte and still stands. A tip is the player's own wallet paying that address (zap.js).




const GAME_INFO_DESCRIPTION_MAX = 500;
const GAME_INFO_WEBSITE_MAX = 200;
const GAME_INFO_SIGNATURE_BYTES = 64;
const GAME_INFO_LIGHTNING_MAX = 120;

/**
 * Refused by name: a description of 0..500 characters, a website that is empty or an https:// address of up to 200, and a
 * tip address that is empty or a Lightning address (name@host, lower case) of up to 120.
 */
function gameInfoFits({ description = '', website = '', lightning = '' } = {}) {
  if (typeof description !== 'string' || description.length > GAME_INFO_DESCRIPTION_MAX)
    return { ok: false, why: `a game's description is a string of at most ${GAME_INFO_DESCRIPTION_MAX} characters` };
  if (typeof website !== 'string' || website.length > GAME_INFO_WEBSITE_MAX || (website !== '' && !/^https:\/\/[^\s/]+(\/\S*)?$/.test(website)))
    return { ok: false, why: `a game's website is empty or an https:// address of at most ${GAME_INFO_WEBSITE_MAX} characters` };
  if (typeof lightning !== 'string' || lightning.length > GAME_INFO_LIGHTNING_MAX
    || (lightning !== '' && (!lightningAddressEndpoint(lightning).ok || lightning !== lightning.trim().toLowerCase())))
    return { ok: false, why: `a game's tip address is empty or a Lightning address (name@host, lower case) of at most ${GAME_INFO_LIGHTNING_MAX} characters` };
  return { ok: true };
}

/** The digest the developer key signs: this game's id, then its description and website, then its tip address if it has one. */
function gameInfoDigest(gameId, info) {
  if (!(gameId instanceof Uint8Array) || gameId.length !== 32) throw new Error('a game id is 32 bytes');
  const fits = gameInfoFits(info);
  if (!fits.ok) throw new Error(fits.why);
  const w = new Writer();
  w.bytes32(gameId); w.str(info.description || ''); w.str(info.website || '');
  if (info.lightning) w.str(info.lightning);
  return taggedHash(TAG.gameInfo, w.finish());
}

/**
 * WHAT A READER SHOWS for a game: its description and website when the manifest's developer key signed them for this game
 * id, else nothing of them (`signed: false` and why). `info` is { description, website, signature (hex or bytes) }.
 */
function gameInfoStands(info, { gameId, manifest, verify } = {}) {
  if (!info) return { ok: false, signed: false, why: 'this game carries no description' };
  let sig;
  try { sig = info.signature instanceof Uint8Array ? info.signature : fromHex(String(info.signature || '')); } catch { sig = null; }
  if (!sig || sig.length !== GAME_INFO_SIGNATURE_BYTES) return { ok: false, signed: false, why: 'its description carries no 64-byte signature' };
  let digest;
  try { digest = gameInfoDigest(gameId, info); } catch (e) { return { ok: false, signed: false, why: e.message }; }
  let good = false;
  try { good = verify(sig, digest, manifest.gameDevPubkey) === true; } catch { good = false; }
  if (!good) return { ok: false, signed: false, why: `its description is not signed by the developer key ${toHex(manifest.gameDevPubkey).slice(0, 16)}` };
  return { ok: true, signed: true, description: info.description || '', website: info.website || '', lightning: info.lightning || '' };
}

/** The info as JSON carries it: the strings (the tip address only when there is one) and the signature in hex. */
const gameInfoJson = (info) => (info ? { description: info.description || '', website: info.website || '',
  ...(info.lightning ? { lightning: info.lightning } : {}),
  signature: info.signature instanceof Uint8Array ? toHex(info.signature) : String(info.signature || '') } : null);

/** What the network store calls a manifest's kind: a replayed or head-to-head game, or an attested market (§0A.7a). */
const gameTypeOf = (m) => (m && m.resultType === 2 ? 'market' : m && m.resultType === 3 ? 'head-to-head game' : 'game');

// ---- arena-client/src/games.js
// SPDX-License-Identifier: LicenseRef-Bitcoin-Arena-1.0
// Copyright (c) 2026 The Bitcoin Arena authors. See LICENSE.
// THE GAMES FIRST, THEN THE GAME'S CLIENT (2026-10-06: "the lobby lists the games the reachable nodes
// host, then that game's rounds; the page loads the plugin's client by the manifest's hash; one wallet and one seed across
// games").
//
// - `fetchGames` asks every named node GET /games and keeps a game only when the manifest a node served hashes to the game
//   id it named (game_id = H(GameManifest), §0A.3) - a node names games, it never vouches for one. A game the page pins in
//   its known-games list is `known`; any other is shown with its developer key and needs the second confirmation (§0A.6).
// - `gameClientFile` fetches one file of a game's client and hands its bytes back only if their SHA-256 is one of the
//   manifest's clients[] - the same hashes the repo's client list pins and client-hash.mjs checks from outside the page. A
//   file the manifest does not name is never run. The page then runs it in the same origin, so the wallet and the seed
//   (sessionStorage / localStorage) are the one the player already has.




const GAMES_ANSWER_MS = 6000;

/**
 * THE GAMES THE NAMED NODES HOST: [{ id, name, title, icon, attested, known, manifest, manifestHex, nodes }], the pinned
 * games first, then by how many nodes host each; and the nodes that did not answer or served something that is not a game.
 */
async function fetchGames({ nodes, fetcher = fetch, answerMs = GAMES_ANSWER_MS } = {}) {
  if (!Array.isArray(nodes) || !nodes.length) throw new Error('the games are asked of the nodes a lobby was named, and it was named none');
  const unique = [...new Set(nodes.map((n) => String(n).replace(/\/+$/, '')))];
  const byId = new Map();
  const refused = [];
  const answers = await Promise.all(unique.map((node) => fetcher(`${node}/games`, { signal: AbortSignal.timeout(answerMs) })
    .then(async (r) => ({ r, body: r.ok ? await r.json() : null }), (e) => ({ e }))));
  for (const [k, node] of unique.entries()) {
    const { r, body, e } = answers[k];
    if (e) { refused.push(`${node}: ${e.message}`); continue; }
    if (!r.ok) { refused.push(`${node}: answered ${r.status}`); continue; }
    for (const g of (body && Array.isArray(body.games)) ? body.games : []) {
      const id = String(g && g.id).toLowerCase();
      let manifest;
      try { manifest = decodeManifest(fromHex(String(g.manifest))); } catch (err) { refused.push(`${node}: game ${id.slice(0, 16)}: ${err.message}`); continue; }
      if (toHex(gameIdOf(manifest)) !== id) { refused.push(`${node}: game ${id.slice(0, 16)}: its manifest is another game`); continue; }
      if (!byId.has(id)) {
        byId.set(id, { id, name: manifest.gameName, title: typeof g.title === 'string' && g.title ? g.title : manifest.gameName,
          icon: typeof g.icon === 'string' && g.icon ? `${node}/${g.icon.replace(/^\/+/, '')}` : null, attested: isAttested(manifest),
          known: Object.prototype.hasOwnProperty.call(KNOWN_GOOD_GAMES, id), devKey: toHex(manifest.gameDevPubkey),
          manifest, manifestHex: String(g.manifest).toLowerCase(), nodes: [],
          // ITS SIGNED DESCRIPTION, AS HANDED: checked against the developer key by checkedGameInfo, never taken
          info: g.info && typeof g.info === 'object' ? g.info : null,
          // WHO PLAYS IT NOW: the highest any seat says - the seats of a committee hold the same entries, so a sum would count
          // each player once per seat
          live: { rounds: 0, players: 0 } });
      }
      const got = byId.get(id);
      // ONE NODE, COUNTED ONCE (2026-10-14 07:42Z, a phone off the tailnet: "28 nodes" for 14): a seat reached at two
      // addresses (its Funnel name and its named tunnel) answers both with the same node key; it hosts the game once
      const key = body && /^[0-9a-f]{64}$/i.test(String(body.node)) ? String(body.node).toLowerCase() : node;
      if (!got.nodeKeys) Object.defineProperty(got, 'nodeKeys', { value: new Set(), enumerable: false });
      if (got.nodeKeys.has(key)) continue;
      got.nodeKeys.add(key);
      got.nodes.push(node);
      if (!got.info && g.info && typeof g.info === 'object') got.info = g.info;
      if (g.live && typeof g.live === 'object') {
        got.live.rounds = Math.max(got.live.rounds, Number(g.live.rounds) || 0);
        got.live.players = Math.max(got.live.players, Number(g.live.players) || 0);
      }
    }
  }
  const games = [...byId.values()].sort((a, b) => (Number(b.known) - Number(a.known)) || (b.nodes.length - a.nodes.length) || (a.name < b.name ? -1 : 1));
  return { games, refused };
}

/**
 * ONE TILE PER GAME, NOT PER VERSION (measured on the v2 page: each game showed twice - its 2026.0.1 manifest
 * and its 2026.0.2 update, the second "No signed description."). Versions of one game share its developer key and name (an
 * update is a new manifest under the same key, §5). Of each, the newest, always (2026-10-26 08:4xZ, the owner: "Version 24 is the newest
 * btc up or down, why is version 13 open? We should always play the newest version" - an older version's live round no longer takes
 * the tile, kanban #685).
 * The others are kept on the tile as `versions` (newest first), so a link naming an older version's id still finds it.
 */
function oneTilePerGame(games) {
  const groups = new Map();
  for (const g of games || []) {
    const key = `${g.devKey}:${g.name}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(g);
  }
  const out = [];
  for (const versions of groups.values()) {
    versions.sort((a, b) => ((b.manifest && b.manifest.version) || 0) - ((a.manifest && a.manifest.version) || 0));
    const shown = versions[0];
    // `older`: the other versions, each with its own info - a description its developer signed for that version's id, which
    // the tile shows while the shown version carries none that stands (checkedGameInfoOfTile)
    out.push(Object.assign({}, shown, { versions: versions.map((g) => g.id), older: versions.filter((g) => g !== shown) }));
  }
  return out;
}

/** The lobby's rows of one game (each row carries its contract's game id as `game`). */
const rowsOfGame = (rows, gameIdHex) => (rows || []).filter((r) => String(r && r.game).toLowerCase() === String(gameIdHex).toLowerCase());

/**
 * ONE FILE OF A GAME'S CLIENT, BY THE MANIFEST'S HASH: its bytes and hash, or a refusal naming the file. `digest(bytes)`
 * is SHA-256, injected (WebCrypto in the page, node:crypto in a test).
 */
async function gameClientFile({ game, url, digest, fetcher = fetch }) {
  if (!game || !game.manifest) throw new Error('a client is loaded for a game whose manifest is held');
  if (typeof digest !== 'function') throw new Error('a client file is checked against its hash, and no digest was injected');
  // EVERY VERSION OF THE GAME ON ITS TILE: a version is a new manifest under the same developer key and name
  // (oneTilePerGame groups only those), so a client file any of them pins is the developer's; the tile may show version 2
  // while the page holds version 3's newer file
  const pinned = new Set([game, ...(Array.isArray(game.older) ? game.older : [])]
    .filter((g) => g && g.manifest && (g === game || (g.name === game.name && toHex(g.manifest.gameDevPubkey || new Uint8Array()) === toHex(game.manifest.gameDevPubkey || new Uint8Array()))))
    .flatMap((g) => (g.manifest.clients || []).map((h) => toHex(h))));
  if (!pinned.size) return { ok: false, why: `${game.name}'s manifest names no client` };
  let r;
  try { r = await fetcher(url, { cache: 'no-store' }); } catch (e) { return { ok: false, why: `${url}: ${e.message}` }; }
  if (!r.ok) return { ok: false, why: `${url}: answered ${r.status}` };
  const bytes = new Uint8Array(await r.arrayBuffer());
  const hash = toHex(new Uint8Array(await digest(bytes)));
  if (!pinned.has(hash)) return { ok: false, why: `${url} hashes to ${hash.slice(0, 16)}, which ${game.name}'s manifest does not name: not run` };
  return { ok: true, bytes, hash };
}

/**
 * A GAME'S SIGNED DESCRIPTION AND WEBSITE (game-info.js): kept only when the manifest's developer key signed
 * them - `verifyEd25519(sig, msg, pub)` may be async (the browser's). Anything else answers null and is not shown.
 */
async function checkedGameInfo(game, verifyEd25519) {
  const info = game && game.info;
  if (!info || typeof info.description !== 'string' || typeof verifyEd25519 !== 'function') return null;
  let digest, sig;
  try { digest = gameInfoDigest(fromHex(game.id), info); sig = fromHex(String(info.signature || '')); } catch { return null; }
  let good = false;
  try { good = (await verifyEd25519(sig, digest, game.manifest.gameDevPubkey)) === true; } catch { good = false; }
  return good ? { description: info.description, website: typeof info.website === 'string' && info.website ? info.website : null,
    lightning: typeof info.lightning === 'string' && info.lightning ? info.lightning : null } : null;
}

/**
 * A TILE'S DESCRIPTION: its own version's, else the newest other version's that its developer signed - each
 * checked against that version's own id; a tile groups only one developer key's versions (oneTilePerGame).
 */
async function checkedGameInfoOfTile(tile, verifyEd25519) {
  for (const g of [tile, ...((tile && tile.older) || [])]) {
    const info = await checkedGameInfo(g, verifyEd25519);
    if (info) return info;
  }
  return null;
}

// ---- arena-client/src/node-discovery.js
// SPDX-License-Identifier: LicenseRef-Bitcoin-Arena-1.0
// Copyright (c) 2026 The Bitcoin Arena authors. See LICENSE.
// THE NODES, FOUND ON THE FLY (2026-10-13: "The client may not have a hard coded node list it must be found on
// the fly"). A page starts from any node it can reach (a bootstrap, not a list), and every census it checks itself - each entry's
// bond and advertisement proved against headers it agreed (client-committee.js) - names the network's nodes: each bond's
// advertisement carries the node's endpoint. Those are the nodes this page talks to from then on, kept for its next start.

/** The https root of a node's advertised endpoint (wss -> https, ws -> http), or null for none. */
function endpointRoot(endpoint) {
  const s = String(endpoint || '').trim();
  if (!/^(wss?|https?):\/\//i.test(s)) return null;
  return s.replace(/^ws(s?):/i, 'http$1:').replace(/\/+$/, '');
}

/** Every node a checked census names, by its advertised endpoint: one root per node key, in the order of their keys. */
function censusEndpoints(entries) {
  const byKey = new Map();
  for (const e of entries || []) {
    const root = endpointRoot(e && e.advert && e.advert.endpoint);
    if (!root || !e.pubkey) continue;
    const k = toHex(e.pubkey);
    if (!byKey.has(k)) byKey.set(k, root);
  }
  return [...byKey.entries()].sort((a, b) => (a[0] < b[0] ? -1 : 1)).map((x) => x[1]);
}

/** `known` with every root of `found` it lacks, appended - nothing known is dropped or reordered. */
function mergeNodes(known, found) {
  const out = [...(known || [])];
  const have = new Set(out.map((n) => String(n).replace(/\/+$/, '')));
  for (const n of found || []) { const r = String(n).replace(/\/+$/, ''); if (!have.has(r)) { have.add(r); out.push(r); } }
  return out;
}

// ---- arena-client/src/season-view.js
// SPDX-License-Identifier: LicenseRef-Bitcoin-Arena-1.0
// Copyright (c) 2026 The Bitcoin Arena authors. See LICENSE.
// THE LEADERBOARD (named the season board until) AS THE PAGE SHOWS IT (docs/PLATFORM-RESEARCH.md item 1, presentation): one game's board
// over the last 7, 30 or 90 days, from a seat's GET /season?game=<name>&days=<n>&scope=network.
//
// The seat built the board (protocol season.js, merged across seats by mergeSeasonAccounts: a round counts only when 3
// seats hand in byte-identical accounts of it), and the board is PRESENTATION, NOT AUTHORITY (0.11): nothing here ranks,
// adds up or pays. This module only turns the answer into lines - the rank and name as the seat gave them, the net in whole
// sats, the best score in the game's own unit, a header, and the viewer's own row marked - and refuses an answer that is
// not a board by name, so the page asks the next seat instead of drawing a broken one.
//
// NO FLOAT EVER TOUCHES AN AMOUNT. A seat sends msat as a decimal string; it is read as a BigInt, and a string that is not
// a whole number (a "1.5", an "1e3", an empty one) refuses the whole answer. The sats shown are the msat divided by 1000
// with the fraction dropped - the MAGNITUDE rounded down, so neither a win nor a loss is ever shown larger than it was
// (-1,999 msat is "-1 sat", not "-2 sat"); the exact msat stays on the row beside it.
//
// DETERMINISTIC AND WITHOUT A DOM: the same answer, title and viewer give the same rows, so a test and the page agree.
// The one function that talks to the network, fetchSeason, is handed its fetch.

/** The windows the page offers (protocol season.js takes 1 to 90 whole days; the seat keeps each one 30 s). */
const SEASON_DAYS_CHOICES = [7, 30, 90];
/** How often an open season view asks again: the seat keeps a season 30 s (SEASON_KEEP_MS), so sooner reads the same. */
const SEASON_POLL_MS = 30000;
/** How long one seat is waited for: a cold network season asks every other seat with an 8 s limit of its own. */
const SEASON_ANSWER_MS = 12000;
/** Rows drawn at most; the viewer's own row is added below them when it ranks further down. */
const SEASON_ROWS_SHOWN = 100;

// A GAME'S SCORE IN ITS OWN UNIT: Tick Tock, Next Block's core signs points in units of 1e-5 (nextblock rules/score.js
// SCORE_SCALE), and the result card prints them with five decimals (ResultSummary.cs Score: 8304450 is 83.04450). A game
// not named here shows the integer its core signed.
const SEASON_SCORE_DECIMALS = { nextblock: 5 };
const SEASON_HEX64 = /^[0-9a-f]{64}$/;
const SEASON_WHOLE = /^-?\d+$/;

/** The path a seat answers a season on: one game by name (every version the seat hosts under it), across the network. */
function seasonPath(game, days) {
  return `/season?game=${encodeURIComponent(String(game || ''))}&days=${Number(days)}&scope=network`;
}

/** msat (a whole-number string, a BigInt or a safe integer) as the signed sats line: "+12 sat", "-3 sat", "0 sat". */
function seasonSats(msat) {
  const m = seasonMsat(msat);
  if (m === null) return null;
  const whole = (m < 0n ? -m : m) / 1000n;
  const sign = whole === 0n ? '' : m < 0n ? '-' : '+';
  return `${sign}${seasonThousands(whole)} sat`;
}

/** A best score as the game's result card prints it, or an en dash when the player has none (a market's pick has no score). */
function seasonScore(score, game) {
  if (score === null || score === undefined) return '\u2013';
  if (!Number.isSafeInteger(score)) return '\u2013';
  const places = SEASON_SCORE_DECIMALS[String(game || '')] || 0;
  if (!places) return String(score);
  const unit = 10 ** places;
  const a = Math.abs(score);
  return `${score < 0 ? '-' : ''}${Math.floor(a / unit)}.${String(a % unit).padStart(places, '0')}`;
}

function seasonMsat(v) {
  if (typeof v === 'bigint') return v;
  if (typeof v === 'number') return Number.isSafeInteger(v) ? BigInt(v) : null;
  if (typeof v === 'string' && SEASON_WHOLE.test(v.trim())) return BigInt(v.trim());
  return null;
}

function seasonThousands(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function seasonCount(n, word) {
  return `${n} ${word}${n === 1 ? '' : 's'}`;
}

/**
 * THE BOARD THE PAGE DRAWS, from one /season answer. `title` is the game as its tile names it ("Tick Tock, Next Block");
 * `viewer` the viewer's identity key(s) in hex - the key a round's lobby record names, which is who the season counts a
 * round under. Answers `{ ok: true, title, game, days, header, foot, players, nodes, rows, mine, more, empty }` - each row
 * `{ rank, player, name, rounds, wins, netMsat, net, sign, bestScore, best, mine }` - or `{ ok: false, why }` for an
 * answer that is not a board.
 */
function seasonView(answer, { title = null, viewer = [], limit = SEASON_ROWS_SHOWN } = {}) {
  if (!answer || typeof answer !== 'object' || Array.isArray(answer)) return { ok: false, why: 'that answer is not a season' };
  if (!Array.isArray(answer.rows)) return { ok: false, why: 'that season lists no rows' };
  const days = Number(answer.days);
  if (!Number.isInteger(days) || days < 1 || days > 90) return { ok: false, why: 'that season names no window of 1 to 90 days' };
  const game = answer.game && typeof answer.game === 'object' && typeof answer.game.name === 'string' ? answer.game.name : null;
  const mineKeys = new Set((Array.isArray(viewer) ? viewer : [viewer]).map((k) => String(k || '').toLowerCase()).filter((k) => SEASON_HEX64.test(k)));
  const rows = [];
  for (const r of answer.rows) {
    if (!r || typeof r !== 'object') return { ok: false, why: 'a season row is not a row' };
    const player = String(r.player || '').toLowerCase();
    if (!SEASON_HEX64.test(player)) return { ok: false, why: 'a season row names no 32-byte player key' };
    if (!Number.isSafeInteger(r.rank) || r.rank < 1) return { ok: false, why: `the row of ${player.slice(0, 8)} has no rank` };
    if (!Number.isSafeInteger(r.rounds) || r.rounds < 0 || !Number.isSafeInteger(r.wins) || r.wins < 0)
      return { ok: false, why: `the row of ${player.slice(0, 8)} counts no rounds or wins` };
    const net = seasonMsat(r.netMsat);
    if (net === null) return { ok: false, why: `the row of ${player.slice(0, 8)} names no whole msat as its net` };
    const best = r.bestScore === null || r.bestScore === undefined ? null : r.bestScore;
    if (best !== null && !Number.isSafeInteger(best)) return { ok: false, why: `the row of ${player.slice(0, 8)} names a best score that is not a whole number` };
    // THE NAME AS THE ROUND RESULT SHOWS IT: the seat sends the player's own name, else the one made from its key; a row
    // without one is shown by its key's first 8 digits, as the result card does (ResultSummary.cs Who)
    const name = typeof r.name === 'string' && r.name.trim() ? r.name.trim() : player.slice(0, 8);
    rows.push({ rank: r.rank, player, name, rounds: r.rounds, wins: r.wins, netMsat: net.toString(), net: seasonSats(net),
      sign: net > 0n ? 1 : net < 0n ? -1 : 0, bestScore: best, best: seasonScore(best, game), mine: mineKeys.has(player) });
  }
  // THE SEAT'S ORDER, NOT OURS: season.js ranked the rows (net, wins, best score, then the key), and the page keeps that
  // order by rank - sorting again by anything else would be a second ranking beside the seat's
  rows.sort((a, b) => a.rank - b.rank);
  // ONLY THE PLAYERS AHEAD (2026-10-15: "only show positive entries"): a row whose net over the window is
  // 0 or below is not drawn - the viewer's own included. The seat ranks by net first, so the rows left keep ranks 1, 2, 3 ...
  const ahead = rows.filter((r) => r.sign > 0);
  const behind = rows.length - ahead.length;
  rows.length = 0; rows.push(...ahead);
  const cap = Number.isSafeInteger(limit) && limit > 0 ? limit : SEASON_ROWS_SHOWN;
  const shown = rows.slice(0, cap);
  const own = rows.find((r) => r.mine) || null;
  // THE VIEWER'S OWN ROW BELOW THE TOP when it ranks further down: a player looks for himself first
  if (own && !shown.includes(own)) shown.push(own);
  const name = String(title || '').trim() || game || 'this game';
  const seats = answer.seats && typeof answer.seats === 'object' ? answer.seats : null;
  // FROM HOW MANY NODES: the seat that answered and every other seat whose account it merged (seats.answered), of itself
  // and every seat it asked (seats.asked) - a board from fewer nodes is a board fewer could confirm
  const nodes = answer.scope === 'network' && seats && Number.isSafeInteger(seats.asked) && Number.isSafeInteger(seats.answered)
    && seats.asked >= 0 && seats.answered >= 0
    ? { answered: Math.min(seats.answered, seats.asked) + 1, asked: seats.asked + 1 } : null;
  const last = days === 1 ? 'last day' : `last ${days} days`;
  const from = nodes ? `from ${nodes.answered} of ${nodes.asked} nodes` : 'from one node only';
  const header = [name, last, `${seasonCount(rows.length, 'player')} ahead`, from].join(' \u00b7 ');
  const counted = Number.isSafeInteger(answer.rounds) && answer.rounds >= 0 ? answer.rounds : null;
  const leftOut = Number.isSafeInteger(answer.leftOut) && answer.leftOut > 0 ? answer.leftOut : 0;
  const agree = Number.isSafeInteger(answer.agree) && answer.agree > 1 ? answer.agree : null;
  const foot = [counted === null ? null : `${seasonCount(counted, 'round')} counted`,
    leftOut ? `${leftOut} left out (not final yet${agree ? `, or fewer than ${agree} nodes agreed` : ''})` : null,
    agree ? `a round counts once ${agree} nodes hold the same account of it` : null].filter(Boolean).join(' \u00b7 ');
  // MORE: the players ranked below the rows drawn, the viewer's own row (drawn below them) not among them
  const more = rows.length - Math.min(rows.length, cap) - (own && rows.indexOf(own) >= cap ? 1 : 0);
  return { ok: true, title: name, game, days, header, foot, players: rows.length, behind, nodes, rows: shown, mine: own, more,
    empty: rows.length ? null : behind ? `Nobody is ahead at ${name} in the ${last}.` : `Nobody has a counted round of ${name} in the ${last}.` };
}

/**
 * ONE SEASON FROM THE FIRST SEAT THAT ANSWERS IT, in the order given: a seat that does not answer within `answerMs`, answers
 * anything but 200, sends no JSON or sends one seasonView refuses falls through to the next. Answers the view with the
 * seat it came from, or `{ ok: false, why, tried }` when none answered. `via` maps a seat's URL to the route the page
 * reaches it by (ARENA_ROUTED_URL).
 */
async function fetchSeason({ nodes, game, days, title = null, viewer = [], fetch, via = (u) => u, answerMs = SEASON_ANSWER_MS, timeout } = {}) {
  if (!Number.isInteger(days) || days < 1 || days > 90)
    return { ok: false, why: 'a season is 1 to 90 whole days', tried: [] };
  if (!game) return { ok: false, why: 'a season is asked for by a game', tried: [] };
  const tried = [];
  for (const n of nodes || []) {
    const seat = String(n || '').replace(/\/+$/, '');
    if (!/^https?:\/\//.test(seat)) continue;
    try {
      const signal = timeout ? timeout(answerMs) : undefined;
      const r = await fetch(via(seat + seasonPath(game, days)), { cache: 'no-store', signal });
      if (!r || !r.ok) { tried.push({ seat, why: `answered ${r ? r.status : 'nothing'}` }); continue; }
      const view = seasonView(await r.json(), { title, viewer });
      if (!view.ok) { tried.push({ seat, why: view.why }); continue; }
      return { ...view, seat };
    } catch (e) {
      tried.push({ seat, why: e && e.message ? e.message : String(e) });
    }
  }
  return { ok: false, why: tried.length ? 'no node answered the season just now' : 'no node to ask', tried };
}

// ---- arena-client/src/badges-view.js
// SPDX-License-Identifier: LicenseRef-Bitcoin-Arena-1.0
// Copyright (c) 2026 The Bitcoin Arena authors. See LICENSE.
// A PLAYER'S BADGES ON THE SEASON BOARD (docs/PLATFORM-RESEARCH.md items 13 and 1, presentation): the small
// icons after a name on the board, from the seats that award NIP-58 badges (arena-node nostr-badges.js, served at
// GET /badges?player=<identity> and GET /badge-definitions; protocol badges.js says who earned what).
//
// THE SAME LAW AS THE BOARD: PRESENTATION, NOT AUTHORITY. A badge moves no sat and ranks nobody; this module only reads what
// the seats answered, keeps what belongs to the game on screen and says it in words. It checks no signature - a badge is a
// line of status, and the page is not where status is proven (a Nostr client checks the events' ids and signatures itself).
//
// WHICH SEATS: a seat awards badges only with ARENA_NOSTR_BADGES (today seats 1 and 7); every other seat answers `on: false`.
// The board's own seats are asked once each for GET /badge-definitions, and the ones that answer `on: true` are the badge
// seats of this board. Each seat awards from the rounds IT holds (the round badges come from the rounds its committees
// settled), so two badge seats can each hold a "first win" for the same player and game, or one holds it and the other does
// not: a player's awards are asked of every badge seat and MERGED BY (d, scope) - one award shown once, whichever seat
// issued it. Where two seats define the same badge, the first seat in the board's order wins (its name, its words, its image).
//
// BOUNDED: one GET /badge-definitions per seat and one GET /badges per player and badge seat, for the board's life (the
// book below), a few at a time; nothing asked once the board is closed, and a closed board's late answers dropped.
//
// DETERMINISTIC AND WITHOUT A DOM: the same answers give the same icons and words, so a test and the page agree. The network
// is reached only through the fetch handed in.

/** How long one seat is waited for, for its definitions or a player's awards: the board is drawn already, so not long. */
const BADGES_ANSWER_MS = 8000;
/** How many badge requests run at once: a board of 100 rows fills in a few at a time, never in one burst of 100. */
const BADGES_AT_ONCE = 4;
/** Icons drawn after one name at most: the catalogue has four, and a phone row has room for few more. */
const BADGES_SHOWN = 5;

// A BADGE'S d, as the protocol catalogue writes it (badges.js D): lowercase letters, digits and dashes, so it is a safe
// part of a path (/badge-image/<d>.svg) and of a class name. A d that is not one is no badge here.
const BADGE_D = /^[a-z0-9][a-z0-9-]{0,63}$/;
const BADGE_HEX64 = /^[0-9a-f]{64}$/;

/**
 * THE BUILT-IN GLYPH of each catalogue badge, for a definition that names no image (a seat with no public base leaves the
 * image tag out, which NIP-58 allows) or an image that does not load: the seat's own medal colours (nostr-badges.js LOOK)
 * and one mark that reads at 16 px. A badge not in the catalogue gets a grey dot.
 */
const BADGE_GLYPHS = Object.freeze({
  'arena-first-win': Object.freeze({ colour: '#f7931a', mark: '1' }),
  'arena-five-rounds': Object.freeze({ colour: '#3aa0ff', mark: '5' }),
  'arena-perfect-run': Object.freeze({ colour: '#ffd166', mark: '★' }),
  'arena-season-top-3': Object.freeze({ colour: '#b06cff', mark: '3' }),
});
const BADGE_GLYPH_OTHER = Object.freeze({ colour: '#8a96a8', mark: '•' });
// THE ORDER ICONS STAND IN: the catalogue's, then any other badge by its d - the same order on every row and every draw
const BADGE_ORDER = Object.keys(BADGE_GLYPHS);

/** The path a seat answers one player's awards on. */
function badgesPath(player) {
  return `/badges?player=${encodeURIComponent(String(player || '').toLowerCase())}`;
}

/** The path a seat serves a badge's image on (server.js GET /badge-image/<d>.svg), or null for a d that is not one. */
function badgeImagePath(d) {
  return BADGE_D.test(String(d)) ? `/badge-image/${d}.svg` : null;
}

/** A badge's glyph: its colour and mark. */
function badgeGlyph(d) {
  return BADGE_GLYPHS[d] || BADGE_GLYPH_OTHER;
}

const badgeTag = (event, name) => {
  const t = event && Array.isArray(event.tags) ? event.tags.find((x) => Array.isArray(x) && x[0] === name) : null;
  return t && typeof t[1] === 'string' ? t[1] : null;
};
const badgeCut = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

/**
 * ONE NIP-58 BADGE DEFINITION (kind 30009) as the page needs it: `{ d, name, description, image }` - `image` whether the
 * definition names one at all (the page then shows the issuing seat's own /badge-image/<d>.svg, never the URL in the tag:
 * the seat is the one place the page already reaches, through its route). A seat serves `{ event, publishedMs }`; a bare
 * event is read the same. Null for one with no well-formed d. The words are cut short: a seat's text never runs a row wide.
 */
function readBadgeDefinition(def) {
  const event = def && typeof def === 'object' && def.event && typeof def.event === 'object' ? def.event : def;
  if (!event || typeof event !== 'object' || event.kind !== 30009) return null;
  const d = badgeTag(event, 'd');
  if (!d || !BADGE_D.test(d)) return null;
  const name = (badgeTag(event, 'name') || '').trim();
  const description = (badgeTag(event, 'description') || '').trim();
  return { d, name: badgeCut(name || d, 60), description: badgeCut(description, 200), image: !!badgeTag(event, 'image') };
}

/**
 * ONE PLAYER'S BADGES IN ONE GAME, merged from the badge seats' answers. `answers`: `[{ seat, answer }]` in the board's seat
 * order, each `answer` a GET /badges body (`{ player, on, awards, definitions }`). Kept: an answer that is `on: true` and
 * names this player; an award of the shown game (`award.game === game` - its round badges, and its weekly board's
 * top 3, whose scope is the game and the week) with a well-formed d and scope, whose event (when sent) names this player in
 * its `p` tag. Each (d, scope) once, the first seat's. Answers `{ player, count, badges }`: `count` the awards kept, and
 * `badges` one entry per d - `{ d, name, description, count, image, glyph, title }`, `image` the defining seat's
 * /badge-image URL (unrouted) or null - in the catalogue's order, at most BADGES_SHOWN.
 */
function mergeBadgeAwards(answers, { player, game } = {}) {
  const who = String(player || '').toLowerCase();
  const kept = new Map();                        // `${d}\n${scope}` -> d
  const defs = new Map();                        // d -> { ...definition, seat }
  for (const { seat, answer } of Array.isArray(answers) ? answers : []) {
    if (!answer || typeof answer !== 'object' || answer.on !== true) continue;
    if (String(answer.player || '').toLowerCase() !== who) continue;
    for (const def of Array.isArray(answer.definitions) ? answer.definitions : []) {
      const r = readBadgeDefinition(def);
      if (r && !defs.has(r.d)) defs.set(r.d, { ...r, seat: String(seat || '').replace(/\/+$/, '') });
    }
    for (const a of Array.isArray(answer.awards) ? answer.awards : []) {
      if (!a || typeof a !== 'object' || !BADGE_D.test(String(a.d))) continue;
      if (typeof a.game !== 'string' || a.game !== game) continue;
      if (typeof a.scope !== 'string' || !a.scope) continue;
      // AN AWARD TO SOMEBODY ELSE is not this player's, whatever row it was asked for: a sent event names its player
      if (a.event && Array.isArray(a.event.tags) && !a.event.tags.some((t) => Array.isArray(t) && t[0] === 'p' && t[1] === who)) continue;
      const k = `${a.d}\n${a.scope}`;
      if (!kept.has(k)) kept.set(k, a.d);
    }
  }
  const byD = new Map();
  for (const d of kept.values()) byD.set(d, (byD.get(d) || 0) + 1);
  const rank = (d) => { const i = BADGE_ORDER.indexOf(d); return i < 0 ? BADGE_ORDER.length : i; };
  const ds = [...byD.keys()].sort((a, b) => rank(a) - rank(b) || (a < b ? -1 : a > b ? 1 : 0));
  const badges = ds.slice(0, BADGES_SHOWN).map((d) => {
    const def = defs.get(d) || { d, name: d, description: '', image: false, seat: '' };
    const count = byD.get(d);
    const image = def.image && /^https?:\/\//.test(def.seat) ? def.seat + badgeImagePath(d) : null;
    return { d, name: def.name, description: def.description, count, image, glyph: badgeGlyph(d), title: badgeTitle({ name: def.name, description: def.description, count }) };
  });
  return { player: who, count: kept.size, badges };
}

/** A badge's tooltip: its name, how often when more than once (a board's top 3 in two weeks), and what earned it. */
function badgeTitle({ name, description = '', count = 1 }) {
  const head = `${name}${count > 1 ? ` ×${count}` : ''}`;
  return description ? `${head}: ${description}` : head;
}

/** The line under the board's header for the viewer's own badges in this game, or null with none. */
function yourBadgesLine(merged) {
  const n = merged && Number.isSafeInteger(merged.count) ? merged.count : 0;
  return n > 0 ? `Your badges: ${n}` : null;
}

/**
 * THE BADGES OF ONE OPEN BOARD: what was asked, what came back, for the board's life - made when a board opens on a game
 * and closed when it closes (or opens on another game), so nothing is asked twice and nothing at all while it is closed.
 *
 * `nodes` the board's seats in order; `game` the game's name; `fetch` / `via` / `timeout` as fetchSeason takes them;
 * `onBadges(player, merged)` is called once per player when its badges are in (an empty merge too, so the page knows).
 * Answers `{ want(player), get(player), close(), seats(), asked }`: want() queues a player once (a second want is nothing),
 * get() is its merge or null while it is not in, seats() the badge seats once known, `asked` the requests made so far.
 */
function badgeBook({ nodes = [], game, fetch, via = (u) => u, timeout, answerMs = BADGES_ANSWER_MS, atOnce = BADGES_AT_ONCE, onBadges = () => {} } = {}) {
  const list = [...new Set((Array.isArray(nodes) ? nodes : []).map((n) => String(n || '').replace(/\/+$/, '')).filter((n) => /^https?:\/\//.test(n)))];
  const got = new Map();                         // player -> merge, or null while asked
  const queue = [];
  const asked = { definitions: 0, badges: 0 };
  let running = 0, closed = false, onSeats = null, known = null;

  const ask = async (url) => {
    const signal = timeout ? timeout(answerMs) : undefined;
    const r = await fetch(via(url), { cache: 'no-store', signal });
    if (!r || !r.ok) throw new Error(`answered ${r ? r.status : 'nothing'}`);
    return r.json();
  };
  // THE BADGE SEATS, found once: every seat of the board asked for its definitions at the same time, the ones `on: true`
  // kept in the board's order. A seat that fails is no badge seat for this board's life - it is asked again on the next.
  const badgeSeats = () => {
    if (!onSeats) onSeats = Promise.all(list.map(async (seat) => {
      if (closed) return null;
      asked.definitions++;
      try { const a = await ask(`${seat}/badge-definitions`); return a && a.on === true ? seat : null; } catch { return null; }
    })).then((xs) => (known = xs.filter(Boolean)));
    return onSeats;
  };
  const run = async (player) => {
    const seats = await badgeSeats();
    const answers = await Promise.all(seats.map(async (seat) => {
      if (closed) return { seat, answer: null };
      asked.badges++;
      try { return { seat, answer: await ask(seat + badgesPath(player)) }; } catch { return { seat, answer: null }; }
    }));
    const merged = mergeBadgeAwards(answers, { player, game });
    got.set(player, merged);
    if (!closed) onBadges(player, merged);
  };
  const pump = () => {
    while (!closed && running < atOnce && queue.length) {
      const player = queue.shift();
      running++;
      run(player).catch(() => {}).finally(() => { running--; pump(); });
    }
  };
  return {
    want(player) {
      const p = String(player || '').toLowerCase();
      if (closed || !game || !BADGE_HEX64.test(p) || got.has(p)) return;
      got.set(p, null);
      queue.push(p);
      pump();
    },
    get: (player) => got.get(String(player || '').toLowerCase()) || null,
    seats: () => known,
    close() { closed = true; queue.length = 0; },
    get asked() { return { ...asked }; },
  };
}

// ---- arena-protocol/src/zap.js
// SPDX-License-Identifier: LicenseRef-Bitcoin-Arena-1.0
// Copyright (c) 2026 The Bitcoin Arena authors. See LICENSE.
/**
 * ZAPS (NIP-57) BETWEEN PLAYERS AND TIPS TO DEVELOPERS, AS RULES.
 *
 * A zap is an LNURL-pay (LUD-06) payment that carries a signed Nostr event: the payer signs a ZAP REQUEST (kind 9734) naming
 * the recipient's key and the amount, hands it to the recipient's LNURL callback as `nostr`, and gets an invoice whose
 * description hash is SHA-256 of exactly that request's JSON. Once paid, the recipient's LNURL server - the key its pay
 * request names as `nostrPubkey` - signs a ZAP RECEIPT (kind 9735) carrying the invoice and the request, and publishes it to
 * the relays the request listed. Anyone can then count a player's zaps without trusting anyone's word: the receipt is
 * signed by the server the recipient chose, the invoice inside it is for the request's amount under the request's hash.
 *
 * No money path of the game changes: a zap is the payer's own wallet (NWC) paying the recipient's own Lightning address.
 * These are the decisions; the fetching, signing and paying are the client's and the server's.
 */



const ZAP_REQUEST_KIND = 9734;
const ZAP_RECEIPT_KIND = 9735;
/** A zap's message, in characters: the request travels in a URL, so it is kept short. */
const ZAP_COMMENT_MAX = 280;
/** Relays a request may name for its receipt. */
const ZAP_RELAYS_MAX = 8;

const ZAP_HEX64 = /^[0-9a-f]{64}$/;
const zapUtf8 = (s) => new TextEncoder().encode(String(s));
const zapTagsNamed = (e, name) => (Array.isArray(e && e.tags) ? e.tags.filter((t) => Array.isArray(t) && t[0] === name) : []);
const zapTagValue = (e, name) => { const t = zapTagsNamed(e, name)[0]; return t ? t[1] : undefined; };

/** NIP-01's id: SHA-256 of [0, pubkey, created_at, kind, tags, content], in hex. */
const nostrEventId = (e) => toHex(sha256(zapUtf8(JSON.stringify([0, e.pubkey, e.created_at, e.kind, e.tags, e.content]))));

/** Is this a NIP-01 event whose id is its own hash and whose signature is its key's? `verify(sig, id, pubkey)` on bytes. */
function nostrEventSigned(e, { verify } = {}) {
  if (!e || typeof e !== 'object') return { ok: false, why: 'that is not an event' };
  if (!ZAP_HEX64.test(String(e.pubkey)) || !ZAP_HEX64.test(String(e.id)) || !/^[0-9a-f]{128}$/.test(String(e.sig)))
    return { ok: false, why: 'an event carries a 32-byte key, a 32-byte id and a 64-byte signature in lower-case hex' };
  if (!Number.isSafeInteger(e.created_at) || !Number.isSafeInteger(e.kind) || !Array.isArray(e.tags) || typeof e.content !== 'string')
    return { ok: false, why: 'an event carries created_at, kind, tags and content' };
  if (!e.tags.every((t) => Array.isArray(t) && t.every((x) => typeof x === 'string')))
    return { ok: false, why: 'every tag is a list of strings' };
  if (nostrEventId(e) !== e.id) return { ok: false, why: 'its id is not the hash of its own fields' };
  if (typeof verify !== 'function') return { ok: false, why: 'no verifier to check its signature' };
  const hex = (h) => Uint8Array.from(h.match(/../g).map((b) => parseInt(b, 16)));
  let good = false;
  try { good = verify(hex(e.sig), hex(e.id), hex(e.pubkey)) === true; } catch { good = false; }
  return good ? { ok: true } : { ok: false, why: `its signature is not ${e.pubkey.slice(0, 16)}'s` };
}

/**
 * DOES THIS PAY REQUEST TAKE ZAPS? A LUD-06 pay request saying `allowsNostr: true` and naming the key its receipts are signed
 * with (`nostrPubkey`). One that does not is still an address a tip can be paid to, without a receipt.
 */
function payRequestTakesZaps(said) {
  if (!said || said.allowsNostr !== true) return { ok: false, why: 'this Lightning address does not take zaps (no allowsNostr)' };
  if (!ZAP_HEX64.test(String(said.nostrPubkey))) return { ok: false, why: 'this Lightning address names no 32-byte nostrPubkey for its receipts' };
  return { ok: true, nostrPubkey: said.nostrPubkey };
}

/**
 * THE ZAP REQUEST TO SIGN (kind 9734), unsigned: the recipient's key, the amount in msat, the relays its receipt goes to,
 * the recipient's LNURL (bech32 of its pay request URL), and - when the zap is for one thing - the event (`e`) or the
 * addressable thing (`a`, e.g. `30762:<seat>:<round>`) it is for. The content is the payer's message.
 */
function zapRequestTemplate({ recipient, amountMsat, relays = [], payRequestUrl = null, comment = '', event = null, address = null } = {}) {
  if (!ZAP_HEX64.test(String(recipient))) throw new Error('a zap names its recipient by a 32-byte key in hex');
  if (typeof amountMsat !== 'bigint' || amountMsat < 1000n) throw new Error('a zap is at least 1 sat, in msat as a bigint');
  const message = String(comment || '');
  if (message.length > ZAP_COMMENT_MAX) throw new Error(`a zap's message is at most ${ZAP_COMMENT_MAX} characters`);
  const named = [...new Set(relays.map(String))];
  if (!named.length || named.length > ZAP_RELAYS_MAX || !named.every((r) => /^wss?:\/\/\S+$/.test(r)))
    throw new Error(`a zap names 1 to ${ZAP_RELAYS_MAX} relays (wss://) its receipt is published to`);
  const tags = [['relays', ...named], ['amount', String(amountMsat)]];
  if (payRequestUrl) tags.push(['lnurl', lnurlFor(payRequestUrl)]);
  tags.push(['p', recipient]);
  if (event) { if (!ZAP_HEX64.test(String(event))) throw new Error('a zapped event is named by its 32-byte id'); tags.push(['e', event]); }
  if (address) tags.push(['a', String(address)]);
  return { kind: ZAP_REQUEST_KIND, tags, content: message };
}

/**
 * WHETHER A ZAP REQUEST STANDS, AS THE LNURL SERVER CHECKS IT (NIP-57 appendix D): signed, exactly one `p`, at most one `e`
 * and one `a`, a `relays` tag, and an `amount` tag - when there is one - equal to the amount the callback was asked for.
 * Answers `{ ok, recipient, relays }` or why not.
 */
function zapRequestStands(request, { amountMsat, verify } = {}) {
  if (!request || request.kind !== ZAP_REQUEST_KIND) return { ok: false, why: `a zap request is a kind ${ZAP_REQUEST_KIND} event` };
  const signed = nostrEventSigned(request, { verify });
  if (!signed.ok) return { ok: false, why: `the zap request: ${signed.why}` };
  const ps = zapTagsNamed(request, 'p');
  if (ps.length !== 1 || !ZAP_HEX64.test(String(ps[0][1]))) return { ok: false, why: 'a zap request names exactly one recipient (p)' };
  if (zapTagsNamed(request, 'e').length > 1) return { ok: false, why: 'a zap request names at most one event (e)' };
  if (zapTagsNamed(request, 'a').length > 1) return { ok: false, why: 'a zap request names at most one address (a)' };
  const relayTag = zapTagsNamed(request, 'relays')[0];
  const relays = relayTag ? relayTag.slice(1).filter((r) => /^wss?:\/\/\S+$/.test(r)).slice(0, ZAP_RELAYS_MAX) : [];
  if (!relays.length) return { ok: false, why: 'a zap request names the relays its receipt goes to' };
  const said = zapTagValue(request, 'amount');
  if (said !== undefined) {
    if (!/^\d{1,15}$/.test(String(said))) return { ok: false, why: 'a zap request\'s amount is a whole number of msat' };
    if (typeof amountMsat === 'bigint' && BigInt(said) !== amountMsat)
      return { ok: false, why: `the zap request is for ${said} msat, and the callback was asked ${amountMsat}` };
  }
  return { ok: true, recipient: ps[0][1], relays, amountMsat: said === undefined ? null : BigInt(said) };
}

/** The callback asked for a zap: exactly `amountMsat`, the signed request as `nostr`, and the recipient's `lnurl` when known. */
function zapCallbackFor({ callback, amountMsat, request, lnurl = null }) {
  const u = new URL(callback);
  u.searchParams.set('amount', String(amountMsat));
  u.searchParams.set('nostr', JSON.stringify(request));
  if (lnurl) u.searchParams.set('lnurl', lnurl);
  return u.toString();
}

/**
 * IS THIS THE INVOICE A ZAP MAY BE PAID WITH? Exactly `amountMsat`, its description hash SHA-256 of the request's JSON as it
 * was sent (`description`, the string), and - when named - on that network.
 */
function zapInvoiceStands({ invoice, amountMsat, description, network = null } = {}) {
  let d;
  try { d = decodeBolt11(String(invoice || '')); } catch (e) { return { ok: false, why: `that is not an invoice: ${e.message}` }; }
  if (d.amountMsat !== amountMsat)
    return { ok: false, why: `the invoice asks ${d.amountMsat === null ? 'any amount' : `${d.amountMsat} msat`}, and the zap is ${amountMsat} msat` };
  if (!d.descriptionHash || toHex(d.descriptionHash) !== toHex(sha256(zapUtf8(description))))
    return { ok: false, why: 'the invoice\'s description hash is not the zap request\'s (NIP-57)' };
  if (network && d.network !== network) return { ok: false, why: `that invoice is for ${d.network}, not ${network}` };
  return { ok: true, paymentHash: d.paymentHash, amountMsat: d.amountMsat, network: d.network };
}

/**
 * THE RECEIPT TO SIGN (kind 9735), unsigned, once the invoice is paid: the request's `p`, `e` and `a`, its signer as `P`, the
 * invoice (`bolt11`), the request's JSON (`description`) and the preimage. created_at is when the invoice was paid.
 */
function zapReceiptTemplate({ request, description, invoice, preimage = null, paidAtS }) {
  const tags = [['p', zapTagValue(request, 'p')]];
  for (const name of ['e', 'a']) { const v = zapTagValue(request, name); if (v !== undefined) tags.push([name, v]); }
  tags.push(['P', request.pubkey], ['bolt11', String(invoice)], ['description', String(description)]);
  if (preimage) tags.push(['preimage', String(preimage)]);
  return { kind: ZAP_RECEIPT_KIND, created_at: paidAtS, tags, content: '' };
}

/**
 * WHETHER A ZAP RECEIPT STANDS (NIP-57 appendix F): signed by the recipient's LNURL server (`nostrPubkey`); its description is
 * a zap request that stands, for the receipt's own recipient; its invoice is for the request's amount under SHA-256 of that
 * description; and, when known, the request names the recipient's LNURL. Answers `{ ok, sender, recipient, amountMsat,
 * comment, event, address, paidAtS }` - what a board counts - or why not. A preimage, when there is one, must hash to the
 * invoice's payment hash.
 */
function zapReceiptStands(receipt, { nostrPubkey, lnurl = null, verify } = {}) {
  if (!receipt || receipt.kind !== ZAP_RECEIPT_KIND) return { ok: false, why: `a zap receipt is a kind ${ZAP_RECEIPT_KIND} event` };
  if (nostrPubkey && receipt.pubkey !== nostrPubkey)
    return { ok: false, why: `the receipt is signed by ${String(receipt.pubkey).slice(0, 16)}, not the recipient's server ${String(nostrPubkey).slice(0, 16)}` };
  const signed = nostrEventSigned(receipt, { verify });
  if (!signed.ok) return { ok: false, why: `the receipt: ${signed.why}` };
  const description = zapTagValue(receipt, 'description');
  let request;
  try { request = JSON.parse(String(description)); } catch { return { ok: false, why: 'the receipt carries no zap request as its description' }; }
  const stands = zapRequestStands(request, { verify });
  if (!stands.ok) return { ok: false, why: stands.why };
  if (stands.amountMsat === null) return { ok: false, why: 'the zap request names no amount, so the receipt cannot be counted' };
  if (zapTagValue(receipt, 'p') !== stands.recipient) return { ok: false, why: 'the receipt is for another recipient than its request' };
  const paid = zapInvoiceStands({ invoice: zapTagValue(receipt, 'bolt11'), amountMsat: stands.amountMsat, description });
  if (!paid.ok) return { ok: false, why: paid.why };
  if (lnurl) {
    const named = zapTagValue(request, 'lnurl');
    if (named !== undefined && String(named).toLowerCase() !== String(lnurl).toLowerCase())
      return { ok: false, why: 'the zap request names another Lightning address than the recipient\'s' };
  }
  const preimage = zapTagValue(receipt, 'preimage');
  if (preimage !== undefined) {
    if (!ZAP_HEX64.test(String(preimage)) || toHex(sha256(Uint8Array.from(preimage.match(/../g).map((b) => parseInt(b, 16))))) !== toHex(paid.paymentHash))
      return { ok: false, why: 'the receipt\'s preimage is not the invoice\'s' };
  }
  return { ok: true, sender: request.pubkey, recipient: stands.recipient, amountMsat: stands.amountMsat, comment: request.content,
    event: zapTagValue(request, 'e') || null, address: zapTagValue(request, 'a') || null, paidAtS: receipt.created_at, receiptId: receipt.id };
}

/** The sum a board shows: receipts that stand, each counted once by its invoice's payment hash. */
function zapTotals(receipts, options = {}) {
  const seen = new Set();
  const counted = [];
  let msat = 0n;
  for (const r of receipts || []) {
    const s = zapReceiptStands(r, options);
    if (!s.ok) continue;
    const key = toHex(decodeBolt11(zapTagValue(r, 'bolt11')).paymentHash);
    if (seen.has(key)) continue;
    seen.add(key); counted.push(s); msat += s.amountMsat;
  }
  return { count: counted.length, msat, zaps: counted };
}

